(1, 1, 1, N'Làm quen & giảm nhạy cảm', N'Quen yên cương, tiếng động lớn, sự điều khiển bằng chân / giọng nói của nài.', 1, 14, N'Low', 25.00, 30.00, N'Cát, đường đất', N'Đi bộ, nước kiệu; tập với tiếng ồn; điều khiển bằng chân và giọng nói.', N'Ngựa bình tĩnh khi có tiếng ồn; điểm phong độ trung bình ≥ 60.'),
(2, 1, 2, N'Phát triển cơ bắp & sức bền', N'Tăng sức bền tim phổi và hệ cơ xương.', 15, 28, N'Moderate', 45.00, 100.00, N'Đồi dốc, cát, đường đất', N'Tăng dần quãng đường; địa hình đa dạng; tập dưới nước 1 buổi/tuần.', N'Thời gian hồi phục ngắn hơn giai đoạn 1; điểm phong độ trung bình ≥ 70.'),
(3, 1, 3, N'Tăng tốc độ', N'Tăng tốc độ, tần suất và độ mở sải vó; xuất phát đúng tín hiệu.', 43, 28, N'High', 70.00, 80.00, N'Đường đua (cỏ / cát)', N'Phi nước đại 200–400 m rồi kéo dài 600–1.000 m; tập ô xuất phát; kiểm soát tốc độ.', N'Tốc độ tối đa tăng ổn định; xuất phát đúng tín hiệu; điểm phong độ trung bình ≥ 75.'),
(4, 1, 4, N'Siết phong độ (Tapering)', N'Tích trữ tối đa năng lượng trước ngày đua.', 71, 14, N'Low', 30.00, 25.00, N'Đường đua', N'Giảm dần cường độ, vẫn giữ độ linh hoạt.', N'bác sĩ thú y xác nhận đủ sức khỏe thi đấu.'),
(5, 2, 1, N'Làm quen & nền tảng', N'Quen yên cương, tiếng động, sự điều khiển của nài.', 1, 14, N'Low', 25.00, 30.00, N'Cát, đường đất', N'Đi bộ, nước kiệu, tập với tiếng ồn.', N'Ngựa bình tĩnh; điểm phong độ trung bình ≥ 60.'),
(6, 2, 2, N'Sức bền', N'Tăng sức bền và sức mạnh chân sau.', 15, 28, N'Moderate', 45.00, 100.00, N'Đồi dốc, đường đất', N'Tăng dần quãng đường; leo dốc; tập dưới nước.', N'Thời gian hồi phục ngắn hơn; điểm phong độ trung bình ≥ 70.'),
(7, 2, 3, N'Kỹ thuật nhảy', N'Nhảy rào đúng kỹ thuật, tiếp đất cân bằng.', 43, 28, N'Moderate', 50.00, 70.00, N'Sân tập chướng ngại', N'Nhảy chướng ngại thấp rồi tăng dần độ cao; giữ nhịp trước rào; tập tiếp đất an toàn.', N'Qua rào chuẩn không chạm; tiếp đất cân bằng; điểm phong độ trung bình ≥ 72.'),
(8, 2, 4, N'Tốc độ trên đường rào', N'Giữ tốc độ đua qua chuỗi rào.', 71, 21, N'High', 70.00, 70.00, N'Đường đua có rào', N'Phi qua chuỗi rào ở tốc độ đua; kiểm soát nhịp giữa các rào.', N'Hoàn thành cự ly có rào ổn định; điểm phong độ trung bình ≥ 75.'),
(9, 2, 5, N'Siết phong độ (Tapering)', N'Tích trữ năng lượng trước ngày đua.', 92, 7, N'Low', 30.00, 15.00, N'Đường đua', N'Giảm cường độ, giữ độ linh hoạt.', N'bác sĩ thú y xác nhận đủ sức khỏe thi đấu.'),
(10, 3, 1, N'Làm quen xe kéo & dây cương', N'Quen dây kéo và xe.', 1, 14, N'Low', 25.00, 30.00, N'Đường đất', N'Đi bộ và nước kiệu chậm có xe kéo.', N'Kéo xe bình tĩnh, giữ thẳng hướng.'),
(11, 3, 2, N'Sức bền nước kiệu', N'Giữ dáng chạy trên quãng đường dài.', 15, 28, N'Moderate', 45.00, 120.00, N'Đường đua', N'Nước kiệu / nước kiệu đi ngang đường dài; không để ngựa chuyển sang phi.', N'Giữ dáng chạy suốt cự ly; điểm phong độ trung bình ≥ 70.'),
(12, 3, 3, N'Tốc độ nước kiệu', N'Tăng tốc độ mà không phá dáng chạy.', 43, 28, N'High', 70.00, 100.00, N'Đường đua', N'Biến tốc nước kiệu nhanh 400–800 m; tập xuất phát sau xe dẫn.', N'Tốc độ tăng, không phá dáng (không phi); điểm phong độ trung bình ≥ 75.'),
(13, 3, 4, N'Siết phong độ (Tapering)', N'Tích trữ năng lượng trước ngày đua.', 71, 14, N'Low', 30.00, 30.00, N'Đường đua', N'Giảm cường độ, giữ độ linh hoạt.', N'bác sĩ thú y xác nhận đủ sức khỏe thi đấu.'),
(14, 4, 1, N'Làm quen & nền tảng', N'Xây nền thể lực, lấy mốc nhịp tim.', 1, 14, N'Low', 25.00, 60.00, N'Đường mòn, cát', N'4 buổi/tuần, đi bộ và nước kiệu chậm 6–8 km; đo nhịp tim nghỉ.', N'Nhịp tim nghỉ ổn định; điểm phong độ trung bình ≥ 60.'),
(15, 4, 2, N'Xây sức bền', N'Chạy bền tốc độ chậm đều.', 15, 28, N'Moderate', 45.00, 220.00, N'Đường mòn', N'4–5 buổi/tuần, mỗi tuần 1 buổi dài 15–25 km.', N'Nhịp tim hồi phục < 64 nhịp/phút trong 15 phút.'),
(16, 4, 3, N'Đồi dốc & nhịp độ', N'Sức mạnh và nhịp độ trên địa hình khó.', 43, 21, N'High', 65.00, 200.00, N'Đồi, đường mòn', N'Leo dốc 2 buổi/tuần; biến tốc nước kiệu nhanh; kiểm tra chân sau mỗi buổi.', N'Hoàn thành buổi dốc không mệt quá mức; điểm phong độ trung bình ≥ 72.'),
(17, 4, 4, N'Mô phỏng thi đấu', N'Quen nhịp độ và trạm kiểm tra của giải.', 64, 14, N'Very High', 75.00, 160.00, N'Địa hình hỗn hợp', N'Mỗi tuần 1 buổi 40–60 km chia chặng; kiểm tra nhịp tim giữa chặng như trạm thú y (≤ 64 nhịp/phút).', N'Qua kiểm tra nhịp tim ở mọi chặng.'),
(18, 4, 5, N'Giảm tải trước giải', N'Tích trữ năng lượng trước ngày đua.', 78, 7, N'Low', 30.00, 40.00, N'Đường mòn', N'Giảm quãng đường, giữ độ linh hoạt.', N'bác sĩ thú y xác nhận đủ sức khỏe thi đấu.'),
(19, 5, 1, N'Nền tảng', N'Làm quen, xây nền thể lực.', 1, 14, N'Low', 25.00, 30.00, N'Cát, đường đất', N'Đi bộ, nước kiệu, tập với tiếng ồn.', N'Ngựa bình tĩnh; điểm phong độ trung bình ≥ 60.'),
(20, 5, 2, N'Phát triển thể lực', N'Tăng sức bền và sức mạnh.', 15, 28, N'Moderate', 45.00, 80.00, N'Địa hình đa dạng', N'Tăng dần quãng đường; tập dưới nước 1 buổi/tuần.', N'Điểm phong độ trung bình ≥ 70.'),
